package com.hrms.attendance.controller;

import com.hrms.attendance.dto.*;import com.hrms.attendance.model.AttendanceStatus;import com.hrms.attendance.service.AttendanceService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/attendance") @Tag(name="Attendance") @SecurityRequirement(name="bearerAuth")
public class AttendanceController {private final AttendanceService service;private final ClockSource clock;public AttendanceController(AttendanceService s,ClockSource c){service=s;clock=c;}
 @PostMapping("/check-in") @PreAuthorize("hasRole('EMPLOYEE')") public ApiResponse<AttendanceResponse> checkIn(@Valid @RequestBody GpsRequest r,@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance check-in recorded",service.checkIn(p,r),clock);}
 @PostMapping("/check-out") @PreAuthorize("hasRole('EMPLOYEE')") public ApiResponse<AttendanceResponse> checkOut(@Valid @RequestBody GpsRequest r,@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance check-out recorded",service.checkOut(p,r),clock);}
 @GetMapping("/me") @PreAuthorize("hasRole('EMPLOYEE')") public ApiResponse<AttendanceResponse> mine(@RequestParam LocalDate date,@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance retrieved",service.mine(p,date).orElse(null),clock);}
 @GetMapping("/me/history") @PreAuthorize("hasRole('EMPLOYEE')") public ApiResponse<AttendancePageResponse> history(@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="workDate")String sortBy,@RequestParam(defaultValue="desc")String sortDirection,@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance history retrieved",service.history(p,fromDate,toDate,page,limit,sortBy,sortDirection),clock);}
 @GetMapping("/me/status") @PreAuthorize("hasRole('EMPLOYEE')") public ApiResponse<AttendanceStatusResponse> status(@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance status retrieved",service.status(p),clock);}
}
